#include <cstddef>
#include <stdexcept>

class Matrix {
public:
    Matrix(int rows, int cols)
        : rows_(rows), cols_(cols), data_(new double[static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols)]) {
        if (rows <= 0 || cols <= 0) {
            delete[] data_;
            data_ = nullptr;
            throw std::invalid_argument("Matrix dimensions must be positive");
        }
    }

    ~Matrix() {
        delete[] data_;
    }

    Matrix(const Matrix& other)
        : rows_(other.rows_), cols_(other.cols_), data_(new double[static_cast<std::size_t>(other.rows_) * static_cast<std::size_t>(other.cols_)]) {
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * static_cast<std::size_t>(cols_); ++i) {
            data_[i] = other.data_[i];
        }
    }

    Matrix(Matrix&& other) noexcept
        : rows_(other.rows_), cols_(other.cols_), data_(other.data_) {
        other.rows_ = 0;
        other.cols_ = 0;
        other.data_ = nullptr;
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            double* new_data = new double[static_cast<std::size_t>(other.rows_) * static_cast<std::size_t>(other.cols_)];
            for (std::size_t i = 0; i < static_cast<std::size_t>(other.rows_) * static_cast<std::size_t>(other.cols_); ++i) {
                new_data[i] = other.data_[i];
            }
            delete[] data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            data_ = new_data;
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            data_ = other.data_;
            other.rows_ = 0;
            other.cols_ = 0;
            other.data_ = nullptr;
        }
        return *this;
    }

    double& at(int r, int c) {
        checkBounds(r, c);
        return data_[static_cast<std::size_t>(r) * static_cast<std::size_t>(cols_) + static_cast<std::size_t>(c)];
    }

    double at(int r, int c) const {
        checkBounds(r, c);
        return data_[static_cast<std::size_t>(r) * static_cast<std::size_t>(cols_) + static_cast<std::size_t>(c)];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix dimensions must match for addition");
        }
        Matrix result(rows_, cols_);
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * static_cast<std::size_t>(cols_); ++i) {
            result.data_[i] = data_[i] + o.data_[i];
        }
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_) {
            throw std::invalid_argument("Matrix dimensions mismatch for multiplication");
        }
        Matrix result(rows_, o.cols_);
        for (int r = 0; r < rows_; ++r) {
            for (int c = 0; c < o.cols_; ++c) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k) {
                    sum += at(r, k) * o.at(k, c);
                }
                result.at(r, c) = sum;
            }
        }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            return false;
        }
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * static_cast<std::size_t>(cols_); ++i) {
            if (data_[i] != o.data_[i]) {
                return false;
            }
        }
        return true;
    }

private:
    void checkBounds(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix index out of range");
        }
    }

    int rows_;
    int cols_;
    double* data_;
};
