struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};
class List {
    Node* head = nullptr;
public:
    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        while (head) {
            Node* next = head->next;
            delete head;
            head = next;
        }
    }
    void push_back(int v) {
        Node* n = new Node(v);
        if (!head) { head = n; return; }
        Node* c = head;
        while (c->next) c = c->next;
        c->next = n;
    }
    void remove_all(int v) {
        while (head && head->value == v) {
            Node* old = head;
            head = head->next;
            delete old;
        }
        Node* c = head;
        while (c && c->next) {
            if (c->next->value == v) {
                Node* old = c->next;
                c->next = old->next;
                delete old;
            } else {
                c = c->next;
            }
        }
    }
    void reverse() {
        Node* prev = nullptr;
        Node* c = head;
        while (c) {
            Node* next = c->next;
            c->next = prev;
            prev = c;
            c = next;
        }
        head = prev;
    }
    std::size_t size() const {
        std::size_t n = 0;
        for (Node* c = head; c; c = c->next) ++n;
        return n;
    }
    int at(std::size_t i) const {
        Node* c = head;
        while (i-- && c) c = c->next;
        if (!c) throw std::out_of_range("List::at");
        return c->value;
    }
};
```

**Bugs fixed:**

1. **`~List()`** — Reassigned `head` to `head->next` after `delete head`, dereferencing freed memory. Now saves `next` before deleting.

2. **`push_back()`** — When the list was empty, it set `head = n` but then continued into the traversal loop, dereferencing the new (empty) node. Added an early return for the empty case.

3. **`remove_all()`** — Two bugs: (a) it started at `head` and only checked `c->next`, so a value matching the head's value was never removed; (b) it advanced `c = c->next` even after deleting `c->next`, skipping elements and dereferencing freed memory. Rewrote to handle head removal first and only advance `c` when no deletion occurs.

4. **`reverse()`** — `c = c->next` was assigned *after* `c->next` had been overwritten with `prev`, so traversal terminated prematurely (only reversing the first two nodes). Now saves `next` before reassigning.

5. **`at()`** — `while (i--) c = c->next;` dereferenced a possibly-null `c` (out-of-range or empty-list access) and returned garbage from an uninitialized pointer. Added a bounds check (`i-- && c`) and throws `std::out_of_range` when out of bounds.

