import heapq


def topo_sort(graph):
    all_nodes = set(graph)
    for prereqs in graph.values():
        all_nodes.update(prereqs)

    indegree = {node: 0 for node in all_nodes}
    dependents = {node: [] for node in all_nodes}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            dependents[prereq].append(node)
            indegree[node] += 1

    heap = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("graph contains a cycle")

    return result
