import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.TreeMap;

public class Library {

    private static final class Loan {
        final String isbn;
        final String title;
        final String member;
        final LocalDate date;

        Loan(String isbn, String title, String member, LocalDate date) {
            this.isbn = isbn;
            this.title = title;
            this.member = member;
            this.date = date;
        }
    }

    private final Map<String, String> titles = new TreeMap<>();
    private final Map<String, Loan> activeLoans = new HashMap<>();

    public void addBook(String isbn, String title) {
        if (isbn == null || title == null) {
            throw new IllegalArgumentException("isbn and title must be non-null");
        }
        if (titles.containsKey(isbn)) {
            throw new IllegalArgumentException("isbn already exists: " + isbn);
        }
        titles.put(isbn, title);
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (isbn == null || member == null || date == null) {
            throw new IllegalArgumentException("arguments must be non-null");
        }
        if (!titles.containsKey(isbn)) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
        if (activeLoans.containsKey(isbn)) {
            throw new IllegalStateException("already borrowed: " + isbn);
        }
        activeLoans.put(isbn, new Loan(isbn, titles.get(isbn), member, date));
    }

    public void giveBack(String isbn) {
        if (isbn == null) {
            throw new IllegalArgumentException("isbn must be non-null");
        }
        Loan loan = activeLoans.remove(isbn);
        if (loan == null) {
            throw new NoSuchElementException("unknown isbn: " + isbn);
        }
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<>();
        for (Loan loan : activeLoans.values()) {
            long duration = java.time.temporal.ChronoUnit.DAYS.between(loan.date, today);
            if (duration > days) {
                result.add(loan.title);
            }
        }
        result.sort(Comparator.naturalOrder());
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> counts = new TreeMap<>();
        for (Loan loan : activeLoans.values()) {
            counts.merge(loan.member, 1, Integer::sum);
        }
        return counts;
    }
}
